{
  "headline": "FDA's records trace our supply to a plant classified OAI 2593 days before the posting",
  "headline_cites": ["E14", "E25"],
  "sentences": [
    {
      "text": "The FDA shortage list shows Fresenius Kabi USA, LLC haloperidol decanoate injection was posted as To Be Discontinued on 2026-01-09.",
      "cites": ["E25"]
    },
    {
      "text": "Our label for Cardinal Health product 55154955305 names Fresenius Kabi USA as the manufacturing plant.",
      "cites": ["E7"]
    },
    {
      "text": "Zydus Lifesciences Limited, another registered plant on our labels, received an OAI classification on 2019-05-03 with the classification known to FDA on 2019-11-14.",
      "cites": ["E14"]
    },
    {
      "text": "That OAI classification occurred 2593 days before the shortage posting date of 2026-01-09.",
      "cites": ["E14", "E25"]
    },
    {
      "text": "Zydus also received a Warning Letter on 2019-10-29 and a VAI inspection ending 2022-08-05.",
      "cites": ["E18", "E15"]
    },
    {
      "text": "Somerset Therapeutics has two ongoing Class II recalls for haloperidol decanoate, one initiated 2024-04-24 for foreign substance and another 2025-03-21 for lack of sterility assurance.",
      "cites": ["E20", "E21"]
    },
    {
      "text": "Corvale East has 15 days on hand, Corvale General 23 days, and Corvale Lakeside 16 days at current usage rates.",
      "cites": ["D1", "D2", "D3"]
    }
  ]
}
